"""Seasonal-naive point forecast with period 7.

forecast for day t is the observed value at day t - 7.
For the first `period` days there is no history, so forecasts start at t = period.
"""
import numpy as np

PERIOD = 7


def seasonal_naive_forecast(y: np.ndarray, t: int) -> float:
    """One-step-ahead seasonal-naive forecast for day t (requires t >= PERIOD)."""
    if t < PERIOD:
        raise ValueError(f"seasonal-naive needs t >= {PERIOD}, got {t}")
    return float(y[t - PERIOD])


def all_forecasts(y: np.ndarray) -> np.ndarray:
    """Forecasts for every day t in [PERIOD, len(y)); index i corresponds to day i + PERIOD."""
    return np.array(
        [seasonal_naive_forecast(y, t) for t in range(PERIOD, len(y))],
        dtype=float,
    )

