import numpy as np

y = np.loadtxt("demand.csv", skiprows=1)
PERIOD=7; BUF=100; T0,T1=200,499

res = {t: float(y[t])-float(y[t-PERIOD]) for t in range(PERIOD,len(y))}
bufs = {t: np.array([res[s] for s in range(t-BUF,t)]) for t in range(T0,T1+1)}

def cov(lo_hi):
    hits=0
    for t in range(T0,T1+1):
        lo,hi = lo_hi(t)
        hits += lo<=y[t]<=hi
    return hits/300

# B) direct buffer quantiles
def b(scale):
    return lambda t: (lambda q10,q90: ((q90+q10)/2 + scale*(q90-q10)/4*np.array([-1,1])))(*np.percentile(bufs[t],[10,90]))
print("direct-quantile: full", round(cov(b(1.0)),4), "halved", round(cov(b(0.5)),4))

# C) bootstrap with different SEED_BASE
for base in (90210, 1234, 777, 20240101, 42):
    def f(scale, base=base):
        def g(t):
            buf=bufs[t]
            rng=np.random.default_rng(base+t)
            draws=float(y[t-PERIOD])+buf[rng.integers(0,buf.size,1000)]
            lo,hi=np.percentile(draws,[10,90])
            m=(lo+hi)/2; w=(hi-lo)*scale/2
            return m-w,m+w
        return g
    print(f"seed_base {base}: full {cov(f(1.0)):.4f} halved {cov(f(0.5)):.4f}")
EOF
